 47	    public Xtw92 createOrderBid(String email, Long productSizeId, int bidPrice) {
 48	        try {
 49	
 50	            validateCreateOrderBidInput(email, productSizeId, bidPrice);
 51	
 52	
 53	            Xjm45 user = userQueryService.findByEmail(email);
 54	
 55	
 56	            Xcc44 productSize = productSizeQueryService.findById(productSizeId)
 57	                    .orElseThrow(() -> new Xpb58Exception("해당 사이즈를 찾을 수 없습니다(ID: " + productSizeId + ")"));
 58	
 59	
 60	            Xhq12 order = orderCommandService.createOrderFromBid(user, productSize, bidPrice);
 61	
 62	
 63	            Xtw92 orderBid = createAndSaveOrderBid(user, productSize, bidPrice, order);
 64	
 65	            return orderBid;
 66	        } catch (Exception e) {
 67	            handleOrderBidCreationException(e, "주문 입찰 생성");
 68	            return null;
 69	        }
 70	    }
