119	    public Xtw92 createInstantOrderBid(String buyerEmail, Long saleBidId, Long addressId,
120	                                          boolean isWarehouseStorage, Xjt45RequestDto paymentRequest) {
121	        try {
122	
123	            validateInstantOrderBidInput(buyerEmail, saleBidId, addressId, paymentRequest);
124	
125	
126	            Xjm45 buyer = userQueryService.findByEmail(buyerEmail);
127	
128	
129	            Xzt63 saleBid = getSaleBidAndValidate(saleBidId);
130	            Xpj42 sale = saleBid.getSale();
131	
132	
133	            Xhq12 order = orderCommandService.createInstantOrder(
134	                    buyer,
135	                    saleBid,
136	                    addressId,
137	                    isWarehouseStorage,
138	                    paymentRequest
139	            );
140	
141	
142	            Xtw92 orderBid = createInstantOrderBid(order, saleBid, sale);
143	
144	            return orderBid;
145	        } catch (Exception e) {
146	            handleOrderBidCreationException(e, "즉시 구매 주문 입찰 생성");
147	            return null;
148	        }
149	    }
